// Package lru implements a fixed-capacity least-recently-used cache with O(1)
// expected-time operations.
package lru

// nilIdx marks the absence of a neighbour in the intrusive linked list.
const nilIdx = -1

type entry struct {
	key, value string
	prev, next int32
}

// Cache is a string-keyed LRU cache. Entries live in a single slice and are
// linked by index, which keeps allocations and GC pressure low. The zero value
// is not usable; construct with New. Cache is not safe for concurrent use.
type Cache struct {
	capacity int
	index    map[string]int32
	entries  []entry
	free     []int32 // slots released by Delete, available for reuse
	head     int32   // most recently used
	tail     int32   // least recently used
}

// New returns an empty cache that holds at most capacity keys.
// It panics if capacity is less than 1.
func New(capacity int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be at least 1")
	}
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32, min(capacity, 1<<16)),
		head:     nilIdx,
		tail:     nilIdx,
	}
}

// Len reports the number of keys currently held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored for key and marks it most recently used.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.entries[i].value, true
}

// Set inserts or overwrites key, marks it most recently used, and evicts the
// least recently used key if the cache exceeds its capacity.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.entries[i].value = value
		c.moveToFront(i)
		return
	}
	var i int32
	switch {
	case len(c.index) >= c.capacity:
		// Reuse the evicted slot directly.
		i = c.tail
		c.unlink(i)
		delete(c.index, c.entries[i].key)
	case len(c.free) > 0:
		i = c.free[len(c.free)-1]
		c.free = c.free[:len(c.free)-1]
	default:
		i = int32(len(c.entries))
		c.entries = append(c.entries, entry{})
	}
	c.entries[i] = entry{key: key, value: value, prev: nilIdx, next: nilIdx}
	c.index[key] = i
	c.pushFront(i)
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.unlink(i)
	delete(c.index, key)
	c.entries[i] = entry{} // drop string references for the GC
	c.free = append(c.free, i)
	return true
}

func (c *Cache) moveToFront(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) pushFront(i int32) {
	e := &c.entries[i]
	e.prev = nilIdx
	e.next = c.head
	if c.head != nilIdx {
		c.entries[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *Cache) unlink(i int32) {
	e := &c.entries[i]
	if e.prev != nilIdx {
		c.entries[e.prev].next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nilIdx {
		c.entries[e.next].prev = e.prev
	} else {
		c.tail = e.prev
	}
	e.prev, e.next = nilIdx, nilIdx
}

package lru

import "testing"

func TestCache(t *testing.T) {
	t.Parallel()
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf(`Get("a") = %q, %v; want "1", true`, v, ok)
	}
	c.Set("c", "3") // evicts b
	if _, ok := c.Get("b"); ok {
		t.Fatal(`Get("b") hit after eviction`)
	}
	if !c.Delete("a") || c.Delete("a") {
		t.Fatal("Delete results wrong")
	}
	if c.Len() != 1 {
		t.Fatalf("Len() = %d, want 1", c.Len())
	}
	c.Set("d", "4")
	c.Set("c", "33") // overwrite refreshes c
	c.Set("e", "5")  // evicts d
	if _, ok := c.Get("d"); ok {
		t.Fatal(`Get("d") hit after eviction`)
	}
	if v, _ := c.Get("c"); v != "33" {
		t.Fatalf(`Get("c") = %q, want "33"`, v)
	}
}

func TestCapacityOne(t *testing.T) {
	t.Parallel()
	c := New(1)
	c.Set("a", "1")
	c.Set("b", "2")
	if _, ok := c.Get("a"); ok || c.Len() != 1 {
		t.Fatal("capacity 1 not enforced")
	}
}

func BenchmarkSetGet(b *testing.B) {
	c := New(1000)
	keys := make([]string, 4096)
	for i := range keys {
		keys[i] = string(rune('a'+i%26)) + string(rune('A'+i/26%26)) + string(rune('0'+i/676))
	}
	i := 0
	for b.Loop() {
		k := keys[i&4095]
		c.Set(k, k)
		c.Get(keys[(i*7)&4095])
		i++
	}
}

// Command app simulates an LRU cache driven by commands read from stdin.
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/internal/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(bufio.NewReaderSize(r, 1<<16))
	sc.Buffer(make([]byte, 0, 1<<12), 1<<20)
	out := bufio.NewWriterSize(w, 1<<16)

	if !sc.Scan() {
		if err := sc.Err(); err != nil {
			return fmt.Errorf("read capacity: %w", err)
		}
		return errors.New("missing capacity")
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(sc.Bytes())))
	if err != nil || capacity < 1 {
		return fmt.Errorf("invalid capacity %q", sc.Bytes())
	}
	cache := lru.New(capacity)

	for sc.Scan() {
		if err := exec(cache, bytes.TrimRight(sc.Bytes(), "\r"), out); err != nil {
			return err
		}
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("read commands: %w", err)
	}
	return out.Flush()
}

// exec applies a single command line to cache, writing any output to out.
// Blank or unrecognised lines are ignored.
func exec(cache *lru.Cache, line []byte, out *bufio.Writer) error {
	cmd, rest, _ := bytes.Cut(line, []byte{' '})
	var err error
	switch string(cmd) {
	case "SET":
		key, value, _ := bytes.Cut(rest, []byte{' '})
		cache.Set(string(key), string(value))
	case "GET":
		// string(rest) in a map lookup does not allocate.
		if v, ok := cache.Get(string(rest)); ok {
			_, err = out.WriteString(v)
		} else {
			_, err = out.WriteString("NULL")
		}
		if err == nil {
			err = out.WriteByte('\n')
		}
	case "DEL":
		if cache.Delete(string(rest)) {
			_, err = out.WriteString("1\n")
		} else {
			_, err = out.WriteString("0\n")
		}
	case "SIZE":
		_, err = out.Write(strconv.AppendInt(out.AvailableBuffer(), int64(cache.Len()), 10))
		if err == nil {
			err = out.WriteByte('\n')
		}
	}
	if err != nil {
		return fmt.Errorf("write output: %w", err)
	}
	return nil
}
